class SqlParser < Racc::Parser

module_eval(<<'...end sql.y/module_eval...', 'sql.y', 59)

# load 'tokenizer.rb'
def parse(str)
  tokenizer = ::Kaigyo::Tokenizer.new(str)
  @q = tokenizer.token_analysis

  pp @q
  
  do_parse
end

def next_token
  @q.shift
end

